INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(1000, 'diligence', '/ˈdɪlɪdʒəns/', 'noun', '{"zh-TW":["盡職調查；勤奮"],"en":["careful and persistent work; also thorough investigation before a transaction"]}', NULL, 'due diligence / financial diligence / exercise diligence', '[{"en":"The acquirer conducted extensive due diligence before completing the deal.","zh-TW":"收購方在完成交易前進行了廣泛的盡職調查。"},{"en":"Her diligence and attention to detail made her invaluable to the team.","zh-TW":"她的勤奮和注重細節使她成為團隊不可或缺的一員。"}]', '{"adjective":"diligent","adverb":"diligently"}', NULL, 3, 1000, NULL),
(1001, 'diligent', '/ˈdɪlɪdʒənt/', 'adjective', '{"zh-TW":["勤勉的；勤奮的"],"en":["showing care and effort in one''s work"]}', NULL, 'diligent worker/student', '[{"en":"She is a diligent employee who always meets her goals.","zh-TW":"她是一位勤勉的員工，總是達成目標。"},{"en":"Diligent research led to the breakthrough.","zh-TW":"勤勉的研究促成了突破。"}]', '{"noun":"diligence","adjective":"diligent","adverb":"diligently"}', NULL, 3, 1001, NULL),
(1002, 'dilution', '/daɪˈluːʃən/', 'noun', '{"zh-TW":["稀釋；股權稀釋"],"en":["the reduction in existing shareholders'' ownership percentage due to new share issuance"]}', NULL, 'equity dilution / avoid dilution / dilution of ownership', '[{"en":"New investors accepted the funding knowing it would cause dilution.","zh-TW":"新投資者在知道會造成稀釋的情況下接受了融資。"},{"en":"Anti-dilution provisions protect early investors in future rounds.","zh-TW":"反稀釋條款在未來融資輪次中保護早期投資者。"}]', '{"verb":"dilute","adjective":"diluted"}', NULL, 3, 1002, NULL),
(1003, 'dimension', '/daɪˈmenʃn/', 'noun', '{"zh-TW":["尺寸；維度；層面"],"en":["a measurable extent","an aspect of something"]}', '{"prefix":{"text":"di-","meaning":"apart (分開)"},"root":{"text":"mens","meaning":"measure (測量)"},"suffix":{"text":"-ion","meaning":"state (狀態)"},"logic":"分開測量的各面向，即「維度」。"}', 'new dimension / three-dimensional', '[{"en":"The room''s dimensions are 5 by 4 meters.","zh-TW":"房間的尺寸是5乘4公尺。"},{"en":"This adds a new dimension to the problem.","zh-TW":"這為問題增添了新的層面。"}]', '{"adjective":"dimensional"}', NULL, 3, 1003, NULL),
(1004, 'diminish', '/dɪˈmɪnɪʃ/', 'verb', '{"zh-TW":["減少；縮小","減少；削弱"],"en":["to make or become less"]}', '{"prefix":{"text":"di-","meaning":"apart (分開)"},"root":{"text":"min","meaning":"small (小)"},"suffix":{"text":"-ish","meaning":"make (使)"},"logic":"使變小，即「減少」。"}', 'diminish in value/importance; diminish in value / diminishing returns', '[{"en":"The value of the investment has diminished.","zh-TW":"投資的價值已經減少。"},{"en":"Nothing can diminish her achievements.","zh-TW":"沒有什麼能削弱她的成就。"},{"en":"His influence has diminished over the years.","zh-TW":"他的影響力逐年減弱。"}]', '{"verb":"diminish","adjective":"diminished"}', NULL, 3, 1004, 669),
(1005, 'diner', '/ˈdaɪnər/', 'noun', '{"zh-TW":["用餐者；小餐館"],"en":["a person eating at a restaurant, or a small restaurant"]}', NULL, 'dine at a diner / regular diner', '[{"en":"The diner across the street is open 24 hours.","zh-TW":"街對面的小餐館全天24小時開放。"},{"en":"Every diner received a complimentary glass of wine.","zh-TW":"每位用餐者獲得了一杯免費葡萄酒。"}]', '{"verb":"dine"}', NULL, 2, 1005, NULL),
(1006, 'dinner', '/ˈdɪnər/', 'noun', '{"zh-TW":["晚餐"],"en":["the main meal of the day, usually in the evening","the main meal of the day"]}', NULL, 'business dinner / dinner party; dinner party / have dinner', '[{"en":"We have a business dinner tonight.","zh-TW":"我們今晚有商務晚餐。"},{"en":"Shall we go out for dinner?","zh-TW":"我們出去吃晚餐好嗎？"},{"en":"What''s for dinner tonight?","zh-TW":"今晚晚餐吃什麼？"},{"en":"Let''s have dinner together.","zh-TW":"一起吃晚餐吧。"}]', '{"noun":"dinner"}', NULL, 2, 1006, NULL),
(1007, 'diploma', '/dɪˈploʊmə/', 'noun', '{"zh-TW":["文憑；畢業證書"],"en":["a certificate awarded after completing a course"]}', NULL, 'high school diploma / diploma program', '[{"en":"He received his diploma at graduation.","zh-TW":"他在畢業典禮上拿到了文憑。"},{"en":"A diploma is required for this job.","zh-TW":"這份工作需要文憑。"}]', NULL, NULL, 3, 1007, NULL),
(1008, 'diplomatic', '/ˌdɪpləˈmætɪk/', 'adjective', '{"zh-TW":["外交的；圓融的"],"en":["relating to managing international relations"]}', NULL, 'diplomatic relations / diplomatic immunity', '[{"en":"They broke off diplomatic relations.","zh-TW":"他們斷絕了外交關係。"},{"en":"She handled the situation diplomatically.","zh-TW":"她圓融地處理了這個情況。"}]', '{"noun":"diplomacy","noun2":"diplomat"}', NULL, 4, 1008, NULL),
(1009, 'direct', '/dɪˈrekt/', 'verb / adjective', '{"zh-TW":["指導；直接的","直接的"],"en":["to manage; without anything in between","going straight without stopping"]}', NULL, 'direct contact/access; direct flight / direct contact', '[{"en":"She directs the marketing department.","zh-TW":"她指導行銷部門。"},{"en":"Is there a direct flight to Tokyo?","zh-TW":"有直飛東京的航班嗎？"},{"en":"He gave a direct answer.","zh-TW":"他給了一個直接的回答。"}]', '{"noun":"direction/director","verb":"direct","adjective":"direct","adverb":"directly","noun2":"director"}', NULL, 2, 1009, 25),
(1010, 'direction', 'dɪˈrɛkʃən', 'noun', '{"zh-TW":["方向；指示","指導"],"en":["the way something moves or faces","an instruction"]}', NULL, 'strategic direction/give directions', '[{"en":"The company needs a clear strategic direction.","zh-TW":"公司需要明確的戰略方向。"}]', '{"verb":"direct","adjective":"directional","adverb":"directionally"}', NULL, 3, 1010, 548),
(1011, 'directive', '/dɪˈrektɪv/', 'noun', '{"zh-TW":["指令；指示"],"en":["an official or authoritative instruction"]}', NULL, 'issue a directive / comply with the directive / management directive', '[{"en":"A directive was issued requiring all systems to be updated by Friday.","zh-TW":"發出了一項指令，要求所有系統在週五前更新。"},{"en":"Staff were briefed on the new directive during the morning meeting.","zh-TW":"員工在早上的會議上被告知了新指令。"}]', '{"adjective":"directive"}', NULL, 3, 1011, 858),
(1012, 'director', '/daɪˈrektər/', 'noun', '{"zh-TW":["董事；總監"],"en":["a person who heads a department or sits on the board of directors"]}', NULL, 'board director / executive director / sales director / marketing director', '[{"en":"She was appointed marketing director after five years at the firm.","zh-TW":"她在公司工作五年後被任命為行銷總監。"},{"en":"The director presented the quarterly results to the board.","zh-TW":"總監向董事會呈報了季度業績。"}]', '{"plural":"directors","verb":"direct"}', NULL, 3, 1012, 334),
(1013, 'dirty', '/ˈdɜːrti/', 'adjective', '{"zh-TW":["髒的"],"en":["not clean; covered in unwanted substances","not clean"]}', NULL, 'dirty work / get dirty; dirty hands / dirty work', '[{"en":"Someone has to do the dirty work.","zh-TW":"總得有人做苦差事。"},{"en":"The warehouse floor was dirty.","zh-TW":"倉庫地板很髒。"},{"en":"Your hands are dirty.","zh-TW":"你的手很髒。"},{"en":"Nobody wants to do the dirty work.","zh-TW":"沒人想做髒活。"}]', '{"adjective":"dirty","verb":"dirty","noun":"dirt"}', NULL, 2, 1013, NULL),
(1014, 'disability', '/ˌdɪsəˈbɪləti/', 'noun', '{"zh-TW":["殘疾；障礙"],"en":["a physical or mental condition that limits ability"]}', NULL, 'learning/physical disability', '[{"en":"The company provides support for employees with disabilities.","zh-TW":"公司為有殘疾的員工提供支援。"},{"en":"Disability benefits are available for those who qualify.","zh-TW":"符合資格者可獲得殘疾福利。"}]', '{"noun":"disability","verb":"disable","adjective":"disabled"}', NULL, 4, 1014, 335),
(1015, 'disappear', '/ˌdɪsəˈpɪr/', 'verb', '{"zh-TW":["消失"],"en":["to become impossible to see"]}', NULL, 'disappear from view / disappear without a trace', '[{"en":"The sun disappeared behind the clouds.","zh-TW":"太陽消失在雲後面。"},{"en":"He disappeared without a trace.","zh-TW":"他消失得無影無蹤。"}]', '{"noun":"disappearance"}', NULL, 3, 1015, NULL),
(1016, 'disappoint', '/ˌdɪsəˈpɔɪnt/', 'verb', '{"zh-TW":["使失望"],"en":["to fail to fulfill the expectations of"]}', NULL, 'deeply disappointed', '[{"en":"The results disappointed the investors.","zh-TW":"結果讓投資者失望了。"},{"en":"I''m disappointed with the service quality.","zh-TW":"我對服務品質感到失望。"}]', '{"noun":"disappointment","verb":"disappoint","adjective":"disappointing/disappointed"}', NULL, 4, 1016, NULL),
(1017, 'disappointed', '/ˌdɪsəˈpɔɪntɪd/', 'adjective', '{"zh-TW":["失望的"],"en":["sad because something was not as good as expected"]}', '{"prefix":{"text":"dis-","meaning":"not (不)"},"root":{"text":"appoint","meaning":"arrange (安排)"},"suffix":{"text":"-ed","meaning":"feeling (感受)"},"logic":"事情沒有按安排進行的感受，即「失望的」。"}', 'deeply disappointed / disappointed with', '[{"en":"She was disappointed with the test results.","zh-TW":"她對考試成績感到失望。"},{"en":"Fans were disappointed by the team''s performance.","zh-TW":"球迷對球隊的表現感到失望。"}]', '{"noun":"disappointment","adjective":"disappointing"}', NULL, 4, 1017, NULL),
(1018, 'disaster', '/dɪˈzæstər/', 'noun', '{"zh-TW":["災難"],"en":["a sudden event causing great damage"]}', '{"prefix":{"text":"dis-","meaning":"bad (不好)"},"root":{"text":"aster","meaning":"star (星)"},"logic":"星象不吉（古人認為災難與凶星有關）。"}', 'natural disaster / disaster relief / disaster management', '[{"en":"The earthquake was a major natural disaster.","zh-TW":"地震是一場重大自然災難。"},{"en":"Disaster relief teams were sent immediately.","zh-TW":"救災隊伍被立即派遣。"}]', '{"adjective":"disastrous"}', NULL, 3, 1018, NULL),
(1019, 'disbursement', '/dɪsˈbɜːrsmənt/', 'noun', '{"zh-TW":["支出；支付"],"en":["the payment of money from a fund"]}', NULL, 'cash disbursement / loan disbursement', '[{"en":"Loan disbursement will occur within 5 days.","zh-TW":"貸款將在5天內撥付。"},{"en":"Track all cash disbursements carefully.","zh-TW":"仔細追蹤所有現金支出。"}]', '{"noun":"disbursement","verb":"disburse"}', NULL, 4, 1019, NULL),
(1020, 'discard', '/dɪˈskɑːrd/', 'verb', '{"zh-TW":["丟棄；拋棄"],"en":["to get rid of something no longer useful"]}', NULL, 'discard old files', '[{"en":"Please discard any outdated documents.","zh-TW":"請丟棄任何過時的文件。"},{"en":"The idea was discarded as impractical.","zh-TW":"這個想法因不切實際而被拋棄。"}]', '{"verb":"discard"}', NULL, 3, 1020, NULL),
(1021, 'discharge', '/dɪsˈtʃɑːrdʒ/', 'noun', '{"zh-TW":["出院；排出"],"en":["the process of releasing a patient from hospital"]}', NULL, 'hospital discharge / discharge date', '[{"en":"The patient was discharged after three days in hospital.","zh-TW":"病患住院三天後出院。"},{"en":"The doctor signed the discharge papers this morning.","zh-TW":"醫生今天早上簽署了出院文件。"}]', '{"verb":"discharge"}', NULL, 3, 1021, 670),
(1022, 'disciplinary', '/ˈdɪsɪplɪneri/', 'adjective', '{"zh-TW":["紀律的；懲戒的"],"en":["relating to punishment or enforcement of rules in a workplace"]}', NULL, 'disciplinary action / disciplinary hearing / disciplinary procedure', '[{"en":"Disciplinary action was taken against the employee.","zh-TW":"對該員工採取了紀律處分。"},{"en":"A formal disciplinary hearing was scheduled for next week.","zh-TW":"正式的紀律聆訊定於下週舉行。"}]', '{"noun":"discipline","verb":"discipline"}', NULL, 4, 1022, NULL),
(1023, 'discipline', '/ˈdɪsəplɪn/', 'noun / verb', '{"zh-TW":["紀律；學科"],"en":["the practice of training people to obey rules","controlled behavior; a branch of knowledge","a branch of knowledge"]}', '{"root":{"text":"disciple","meaning":"learner (學習者)"},"logic":"學習者應遵守的規範，即「紀律」。"}', 'maintain discipline; self-discipline / academic discipline; self-discipline / academic discipline / maintain discipline', '[{"en":"Good discipline is essential in the workplace.","zh-TW":"良好的紀律在職場是必要的。"},{"en":"Marketing is a rapidly changing discipline.","zh-TW":"行銷是一個快速變化的學科。"},{"en":"Success requires discipline.","zh-TW":"成功需要紀律。"},{"en":"Biology is a scientific discipline.","zh-TW":"生物學是一門科學學科。"},{"en":"Success requires discipline and hard work.","zh-TW":"成功需要紀律和努力。"},{"en":"Psychology is a fascinating discipline.","zh-TW":"心理學是一門迷人的學科。"}]', '{"noun":"discipline","verb":"discipline","adjective":"disciplined"}', NULL, 4, 1023, NULL),
(1024, 'disclaimer', '/dɪsˈkleɪmər/', 'noun', '{"zh-TW":["免責聲明"],"en":["a statement denying responsibility for something"]}', NULL, 'include a disclaimer / legal disclaimer', '[{"en":"The report includes a disclaimer about the accuracy of predictions.","zh-TW":"報告包含關於預測準確性的免責聲明。"},{"en":"All marketing materials must include the required legal disclaimer.","zh-TW":"所有行銷材料必須包含所需的法律免責聲明。"}]', '{"verb":"disclaim"}', NULL, 4, 1024, NULL),
(1025, 'disclose', '/dɪˈskloʊz/', 'verb', '{"zh-TW":["揭露；公開"],"en":["to make information known publicly"]}', NULL, 'disclose information', '[{"en":"The company refused to disclose its financial data.","zh-TW":"公司拒絕公開其財務數據。"},{"en":"He disclosed the details of the agreement.","zh-TW":"他揭露了協議的細節。"}]', '{"noun":"disclosure","verb":"disclose"}', NULL, 3, 1025, 671),
(1026, 'discount', '/ˈdɪskaʊnt/', 'noun / verb', '{"zh-TW":["折扣；打折"],"en":["a reduction in the usual price"]}', NULL, 'offer/give a discount', '[{"en":"We offer a 20% discount for bulk orders.","zh-TW":"我們對大量訂單提供八折優惠。"},{"en":"The store discounted all winter items.","zh-TW":"商店對所有冬季商品打折。"}]', '{"noun":"discount","verb":"discount","adjective":"discounted"}', NULL, 3, 1026, 105),
(1027, 'discover', '/dɪˈskʌvər/', 'verb', '{"zh-TW":["發現"],"en":["to find something for the first time"]}', NULL, 'discover a solution; discover a new species / discover the truth', '[{"en":"Scientists discovered a new treatment.","zh-TW":"科學家發現了一種新療法。"},{"en":"She discovered an error in the report.","zh-TW":"她在報告中發現了一個錯誤。"},{"en":"Columbus discovered America in 1492.","zh-TW":"哥倫布在1492年發現了美洲。"},{"en":"She discovered the truth about her past.","zh-TW":"她發現了關於她過去的真相。"}]', '{"noun":"discovery","verb":"discover"}', NULL, 3, 1027, NULL),
(1028, 'discrepancy', '/dɪˈskrepənsi/', 'noun', '{"zh-TW":["差異；不一致"],"en":["a lack of agreement between two or more facts or claims"]}', NULL, 'financial discrepancy / discrepancy in the records / resolve a discrepancy', '[{"en":"A discrepancy was found between the invoice and the purchase order.","zh-TW":"發票和採購訂單之間發現了差異。"},{"en":"The auditor flagged a discrepancy in the accounts receivable balance.","zh-TW":"審計師標記了應收帳款餘額中的差異。"}]', '{"adjective":"discrepant","plural":"discrepancies"}', NULL, 4, 1028, NULL),
(1029, 'discretion', '/dɪˈskreʃən/', 'noun', '{"zh-TW":["判斷力；酌情權"],"en":["the freedom to decide what should be done"]}', NULL, 'at one''s discretion', '[{"en":"Use your own discretion when handling complaints.","zh-TW":"處理投訴時請自行判斷。"},{"en":"Bonuses are awarded at management''s discretion.","zh-TW":"獎金由管理層酌情發放。"}]', '{"noun":"discretion","adjective":"discreet/discretionary"}', NULL, 4, 1029, 550),
(1030, 'discriminate', '/dɪˈskrɪmɪneɪt/', 'verb', '{"zh-TW":["歧視；區別"],"en":["to treat unfairly based on prejudice"]}', NULL, 'discriminate against', '[{"en":"It is illegal to discriminate against employees based on age.","zh-TW":"基於年齡歧視員工是違法的。"},{"en":"Can you discriminate between the two options?","zh-TW":"你能區分這兩個選項嗎？"}]', '{"noun":"discrimination","verb":"discriminate","adjective":"discriminatory"}', NULL, 4, 1030, NULL),
(1031, 'discrimination', '/dɪˌskrɪmɪˈneɪʃn/', 'noun', '{"zh-TW":["歧視；辨別"],"en":["unjust treatment based on race, age, or gender"]}', '{"prefix":{"text":"dis-","meaning":"apart (分開)"},"root":{"text":"crimin","meaning":"separate (區分)"},"suffix":{"text":"-ation","meaning":"act of (行為)"},"logic":"把人分開區別對待，即「歧視」。"}', 'racial discrimination / gender discrimination', '[{"en":"Discrimination based on age is illegal.","zh-TW":"年齡歧視是違法的。"},{"en":"The company has a strict anti-discrimination policy.","zh-TW":"公司有嚴格的反歧視政策。"}]', '{"verb":"discriminate","adjective":"discriminatory"}', NULL, 5, 1031, NULL),
(1032, 'discuss', '/dɪˈskʌs/', 'verb', '{"zh-TW":["討論"],"en":["to talk about something in detail","to talk about something with others"]}', NULL, 'discuss the matter/issue; discuss a topic / discuss the matter', '[{"en":"We need to discuss the budget proposal.","zh-TW":"我們需要討論預算提案。"},{"en":"The team discussed several options.","zh-TW":"團隊討論了幾個方案。"},{"en":"Let''s discuss this later.","zh-TW":"我們稍後再討論這件事。"},{"en":"They discussed the proposal at the meeting.","zh-TW":"他們在會議上討論了提案。"}]', '{"noun":"discussion","verb":"discuss"}', NULL, 3, 1032, 106),
(1033, 'discussion', 'dɪˈskʌʃən', 'noun', '{"zh-TW":["討論；商議","辯論"],"en":["a conversation about something","an examination of issues"]}', NULL, 'open discussion/group discussion', '[{"en":"The manager encouraged open discussion.","zh-TW":"經理鼓勵開放的討論。"}]', '{"verb":"discuss","adjective":"discussable"}', NULL, 4, 1033, NULL),
(1034, 'disembark', '/ˌdɪsɪmˈbɑːrk/', 'verb', '{"zh-TW":["下船；下機"],"en":["to leave a ship or aircraft"]}', NULL, 'disembark passengers / disembark at the port', '[{"en":"Passengers were asked to disembark in an orderly manner.","zh-TW":"乘客被要求有秩序地下船。"},{"en":"We disembarked at the port of call.","zh-TW":"我們在停靠港口下船。"}]', '{"noun":"disembarkation"}', NULL, 3, 1034, NULL),
(1035, 'dish', '/dɪʃ/', 'noun', '{"zh-TW":["菜餚；碗盤"],"en":["a type of food prepared in a particular way"]}', NULL, 'signature dish / main dish', '[{"en":"The chef''s signature dish is the braised short rib.","zh-TW":"主廚的招牌菜是紅燒牛小排。"},{"en":"Each dish is made from locally sourced ingredients.","zh-TW":"每道菜餚都使用當地採購的食材製作。"}]', NULL, NULL, 1, 1035, NULL),
(1036, 'dismiss', '/dɪˈsmɪs/', 'verb', '{"zh-TW":["解僱；駁回","解僱；駁回；不理會"],"en":["to remove from a job; to reject","to send away","to refuse to consider"]}', '{"prefix":{"text":"dis-","meaning":"away (離開)"},"root":{"text":"miss","meaning":"send (送)"},"logic":"把人送走，即「解僱」或「不理會」。"}', 'dismiss an employee/idea; dismiss an employee / dismiss the idea / dismiss the case', '[{"en":"He was dismissed for misconduct.","zh-TW":"他因行為不當被解僱。"},{"en":"The court dismissed the case.","zh-TW":"法院駁回了此案。"},{"en":"The manager dismissed the complaint.","zh-TW":"經理駁回了投訴。"},{"en":"You shouldn''t dismiss his suggestions so quickly.","zh-TW":"你不應該這麼快就否定他的建議。"}]', '{"noun":"dismissal","verb":"dismiss"}', NULL, 3, 1036, NULL),
(1037, 'dismissal', '/dɪsˈmɪsəl/', 'noun', '{"zh-TW":["解僱；免職"],"en":["the act of terminating someone''s employment"]}', NULL, 'wrongful dismissal / dismissal procedure', '[{"en":"The dismissal was considered unfair by the labor board.","zh-TW":"解僱被勞動委員會認定為不公平。"},{"en":"All dismissals must follow the company''s formal procedures.","zh-TW":"所有解僱必須遵循公司的正式程序。"}]', '{"verb":"dismiss","adjective":"dismissed"}', NULL, 3, 1037, NULL),
(1038, 'disorder', '/dɪsˈɔːrdər/', 'noun', '{"zh-TW":["失調；混亂"],"en":["a state of confusion","a medical condition"]}', '{"prefix":{"text":"dis-","meaning":"not (不)"},"root":{"text":"order","meaning":"order (秩序)"},"logic":"沒有秩序，即「混亂」。"}', 'mental disorder / eating disorder / in disorder', '[{"en":"The room was in complete disorder.","zh-TW":"房間完全一片混亂。"},{"en":"She was diagnosed with an anxiety disorder.","zh-TW":"她被診斷出焦慮症。"}]', '{"adjective":"disordered","adjective2":"disorderly"}', NULL, 3, 1038, NULL),
(1039, 'disparity', '/dɪˈspærɪti/', 'noun', '{"zh-TW":["差距；懸殊"],"en":["a great difference or inequality between groups or figures"]}', NULL, 'income disparity / pay disparity / reduce disparity', '[{"en":"A significant pay disparity was identified between junior and senior staff.","zh-TW":"在初級和高級員工之間識別了顯著的薪資差距。"},{"en":"The report highlighted regional disparities in economic growth.","zh-TW":"報告強調了經濟增長的地區差距。"}]', '{"adjective":"disparate","adverb":"disparately"}', NULL, 3, 1039, NULL),
(1040, 'dispatch', '/dɪˈspætʃ/', 'verb / noun', '{"zh-TW":["派遣；發送"],"en":["to send off to a destination"]}', NULL, 'dispatch goods/a team', '[{"en":"The order was dispatched this morning.","zh-TW":"訂單今早已發出。"},{"en":"A repair team was dispatched immediately.","zh-TW":"維修團隊立即被派遣。"}]', '{"noun":"dispatch","verb":"dispatch"}', NULL, 3, 1040, NULL),
(1041, 'display', '/dɪˈspleɪ/', 'verb / noun', '{"zh-TW":["展示；顯示","展示；陳列"],"en":["to show something publicly","an arrangement of items for public viewing"]}', '{"prefix":{"text":"dis-","meaning":"apart (分開)"},"root":{"text":"play","meaning":"fold (展開)"},"logic":"展開來讓人看，即「展示」。"}', 'on display; on display / window display', '[{"en":"The products are displayed in the window.","zh-TW":"產品展示在櫥窗中。"},{"en":"The artwork is on display until March.","zh-TW":"藝術品展出至三月。"},{"en":"The new products are on display in the window.","zh-TW":"新產品正在櫥窗展示。"},{"en":"The museum has an impressive display of artifacts.","zh-TW":"博物館有令人印象深刻的文物展示。"}]', '{"noun":"display","verb":"display"}', NULL, 3, 1041, NULL),
(1042, 'disposal', '/dɪˈspoʊzl/', 'noun', '{"zh-TW":["處理；處置"],"en":["the act of getting rid of something"]}', '{"prefix":{"text":"dis-","meaning":"apart (分開)"},"root":{"text":"pos","meaning":"put (放置)"},"suffix":{"text":"-al","meaning":"act of (行為)"},"logic":"把東西放到一邊去，即「處置」。"}', 'waste disposal / at one''s disposal', '[{"en":"Proper waste disposal protects the environment.","zh-TW":"適當的廢物處理保護環境。"},{"en":"I am at your disposal.","zh-TW":"我隨時為您效勞。"}]', '{"verb":"dispose","adjective":"disposable"}', NULL, 3, 1042, NULL),
(1043, 'dispose', '/dɪˈspoʊz/', 'verb', '{"zh-TW":["處理；丟棄"],"en":["to get rid of; to arrange"]}', NULL, 'dispose of waste', '[{"en":"Please dispose of waste properly.","zh-TW":"請正確處理廢棄物。"},{"en":"The company disposed of its old equipment.","zh-TW":"公司處理了舊設備。"}]', '{"noun":"disposal/disposition","verb":"dispose","adjective":"disposable"}', NULL, 3, 1043, 336),
(1044, 'dispute', '/dɪˈspjuːt/', 'noun / verb', '{"zh-TW":["爭議；爭論","爭議；糾紛"],"en":["a disagreement or argument"]}', '{"prefix":{"text":"dis-","meaning":"apart (分開)"},"root":{"text":"pute","meaning":"think (思考)"},"logic":"想法分歧，即「爭議」。"}', 'resolve/settle a dispute; legal dispute / labor dispute / settle a dispute', '[{"en":"The dispute was settled out of court.","zh-TW":"爭議在庭外解決了。"},{"en":"They disputed the accuracy of the report.","zh-TW":"他們對報告的準確性提出異議。"},{"en":"The labor dispute lasted several weeks.","zh-TW":"勞資糾紛持續了好幾週。"},{"en":"They settled the dispute out of court.","zh-TW":"他們在庭外解決了糾紛。"}]', '{"noun":"dispute","verb":"dispute"}', NULL, 3, 1044, NULL),
(1045, 'disrupt', '/dɪsˈrʌpt/', 'verb', '{"zh-TW":["擾亂；中斷"],"en":["to interrupt the normal course of"]}', NULL, 'disrupt operations/services', '[{"en":"The strike disrupted public transportation.","zh-TW":"罷工擾亂了公共交通。"},{"en":"New technology is disrupting traditional industries.","zh-TW":"新技術正在顛覆傳統產業。"}]', '{"noun":"disruption","verb":"disrupt","adjective":"disruptive"}', NULL, 3, 1045, NULL),
(1046, 'disruption', '/dɪˈsrʌpʃən/', 'noun', '{"zh-TW":["顛覆；中斷"],"en":["a radical change that displaces an established market or product"]}', NULL, 'disruptive technology / market disruption / supply chain disruption', '[{"en":"The digital disruption of retail forced many stores to close.","zh-TW":"零售業的數位顛覆迫使許多商店關閉。"},{"en":"Startups thrive by creating disruption in established industries.","zh-TW":"新創公司通過在既有行業中創造顛覆而蓬勃發展。"}]', '{"verb":"disrupt","adjective":"disruptive","noun":"disruptor"}', NULL, 4, 1046, NULL),
(1047, 'dissertation', '/ˌdɪsərˈteɪʃən/', 'noun', '{"zh-TW":["論文；學位論文"],"en":["a long essay on a subject for a university degree"]}', NULL, 'doctoral dissertation / write a dissertation', '[{"en":"She wrote her dissertation on market behavior.","zh-TW":"她的論文主題是市場行為。"},{"en":"His dissertation was published as a book.","zh-TW":"他的論文出版成書了。"}]', '{"noun":"dissertation"}', NULL, 4, 1047, NULL),
(1048, 'dissolve', '/dɪˈzɑːlv/', 'verb', '{"zh-TW":["解散；溶解"],"en":["to officially end; to mix into a liquid"]}', NULL, 'dissolve a partnership', '[{"en":"The partnership was dissolved last year.","zh-TW":"合夥關係去年解散了。"},{"en":"Sugar dissolves in water.","zh-TW":"糖溶解在水中。"}]', '{"noun":"dissolution","verb":"dissolve"}', NULL, 3, 1048, NULL),
(1049, 'distance', '/ˈdɪstəns/', 'noun', '{"zh-TW":["距離"],"en":["the space between two points"]}', NULL, 'long distance / keep one''s distance', '[{"en":"What''s the distance to the airport?","zh-TW":"到機場有多遠？"},{"en":"Keep your distance from the edge.","zh-TW":"離邊緣遠一點。"}]', '{"adjective":"distant"}', NULL, 3, 1049, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(1050, 'distinct', '/dɪˈstɪŋkt/', 'adjective', '{"zh-TW":["明顯的；不同的","不同的；明顯的"],"en":["clearly different or separate"]}', '{"prefix":{"text":"dis-","meaning":"apart (分開)"},"root":{"text":"tinct","meaning":"prick/mark (刺/標記)"},"logic":"被標記而分開的，即「不同的」。"}', 'distinct advantage/difference; distinct difference / distinct advantage / distinct from', '[{"en":"There is a distinct difference between the two.","zh-TW":"兩者之間有明顯的區別。"},{"en":"The product has a distinct advantage.","zh-TW":"該產品有明顯的優勢。"},{"en":"The two species are distinct from each other.","zh-TW":"這兩個物種彼此不同。"},{"en":"There is a distinct possibility of rain.","zh-TW":"有明顯下雨的可能性。"}]', '{"noun":"distinction","adjective":"distinct/distinctive","adverb":"distinctly"}', NULL, 3, 1050, NULL),
(1051, 'distinguish', '/dɪˈstɪŋɡwɪʃ/', 'verb', '{"zh-TW":["區分；辨別"],"en":["to recognize differences between things"]}', '{"prefix":{"text":"dis-","meaning":"apart (分開)"},"root":{"text":"sting","meaning":"prick/mark (刺/標記)"},"suffix":{"text":"-uish","meaning":"make (使)"},"logic":"使標記分開，即「區分」。"}', 'distinguish between/from; distinguish between / distinguish oneself', '[{"en":"It''s hard to distinguish the original from the copy.","zh-TW":"很難區分原件和副本。"},{"en":"What distinguishes our brand from competitors?","zh-TW":"什麼使我們的品牌與競爭對手不同？"},{"en":"It is important to distinguish fact from opinion.","zh-TW":"區分事實和意見很重要。"},{"en":"She distinguished herself in her field.","zh-TW":"她在自己的領域中出類拔萃。"}]', '{"adjective":"distinguished","verb":"distinguish","adjective2":"distinguishable"}', NULL, 4, 1051, NULL),
(1052, 'distribute', '/dɪˈstrɪbjuːt/', 'verb', '{"zh-TW":["分配；分發"],"en":["to give shares of something to several people"]}', '{"prefix":{"text":"dis-","meaning":"apart (分開)"},"root":{"text":"tribute","meaning":"assign (分派)"},"logic":"分開指派給各人，即「分配」。"}', 'distribute evenly/widely; distribute evenly / distribute resources', '[{"en":"The company distributes products worldwide.","zh-TW":"公司在全球分銷產品。"},{"en":"Profits are distributed among shareholders.","zh-TW":"利潤分配給股東。"},{"en":"The charity distributes food to the homeless.","zh-TW":"慈善機構向無家可歸者分發食物。"}]', '{"noun":"distribution/distributor","verb":"distribute","noun2":"distributor"}', NULL, 4, 1052, 337),
(1053, 'distribution', '/ˌdɪstrɪˈbjuːʃən/', 'noun', '{"zh-TW":["分配；配送"],"en":["the process of supplying goods to retailers or customers"]}', NULL, 'distribution network / distribution center', '[{"en":"The company has a wide distribution network across Asia.","zh-TW":"公司在亞洲擁有廣泛的配送網絡。"},{"en":"The distribution center processes thousands of orders daily.","zh-TW":"配送中心每天處理數千個訂單。"}]', '{"verb":"distribute","noun":"distributor","adjective":"distributed"}', NULL, 4, 1053, 26),
(1054, 'distributor', '/dɪˈstrɪbjʊtər/', 'noun', '{"zh-TW":["批發商；分銷商"],"en":["a company that supplies goods to retailers or other businesses"]}', NULL, 'exclusive distributor / appoint a distributor / distributor agreement', '[{"en":"The company appointed an exclusive distributor for Southeast Asia.","zh-TW":"公司為東南亞任命了獨家分銷商。"},{"en":"The distributor warehouses products before shipping to retailers.","zh-TW":"分銷商在向零售商發貨前倉儲產品。"}]', '{"plural":"distributors","verb":"distribute"}', NULL, 4, 1054, NULL),
(1055, 'disturb', '/dɪˈstɜːrb/', 'verb', '{"zh-TW":["打擾；使不安"],"en":["to interrupt or cause concern"]}', '{"prefix":{"text":"dis-","meaning":"thoroughly (徹底)"},"root":{"text":"turb","meaning":"confuse (混亂)"},"logic":"徹底使其混亂，即「打擾」。"}', 'do not disturb / disturb the peace', '[{"en":"Please do not disturb me while I''m working.","zh-TW":"我工作時請不要打擾我。"},{"en":"The news disturbed her deeply.","zh-TW":"這個消息讓她深感不安。"}]', '{"noun":"disturbance","adjective":"disturbing"}', NULL, 3, 1055, NULL),
(1056, 'diverse', '/daɪˈvɜːrs/', 'adjective', '{"zh-TW":["多樣的；多元的","多樣的；不同的"],"en":["showing great variety","showing a great deal of variety"]}', '{"prefix":{"text":"di-","meaning":"apart (分開)"},"root":{"text":"verse","meaning":"turn (轉)"},"logic":"朝不同方向轉的，即「多樣的」。"}', 'diverse workforce/portfolio; diverse population / culturally diverse', '[{"en":"We have a diverse team from many backgrounds.","zh-TW":"我們有來自不同背景的多元團隊。"},{"en":"A diverse portfolio reduces risk.","zh-TW":"多元化的投資組合可以降低風險。"},{"en":"The city has a diverse population.","zh-TW":"這座城市有多元的人口。"},{"en":"We need a more diverse team.","zh-TW":"我們需要一個更多元的團隊。"}]', '{"noun":"diversity/diversification","verb":"diversify","adjective":"diverse"}', NULL, 3, 1056, NULL),
(1057, 'diversification', '/daɪˌvɜːrsɪfɪˈkeɪʃən/', 'noun', '{"zh-TW":["多元化"],"en":["the process of expanding into different areas"]}', NULL, 'portfolio diversification / market diversification', '[{"en":"Diversification reduces investment risk.","zh-TW":"多元化降低投資風險。"},{"en":"Market diversification is key to growth.","zh-TW":"市場多元化是成長的關鍵。"}]', '{"noun":"diversification","verb":"diversify","adjective":"diversified"}', NULL, 5, 1057, NULL),
(1058, 'diversify', 'daɪˈvɜːrsɪfaɪ', 'verb', '{"zh-TW":["多樣化；分散","多角化"],"en":["to vary or widen range","to expand into new areas"]}', NULL, 'diversify investments/diversify products', '[{"en":"We plan to diversify our product line.","zh-TW":"我們計畫使產品線多元化。"}]', '{"noun":"diversification","adjective":"diversified"}', NULL, 3, 1058, 673),
(1059, 'diversity', '/daɪˈvɜːrsɪti/', 'noun', '{"zh-TW":["多元性；多樣性"],"en":["the inclusion of people from various backgrounds, identities, and experiences"]}', NULL, 'workplace diversity / diversity and inclusion / promote diversity', '[{"en":"The company launched programs to increase diversity in leadership.","zh-TW":"公司推出計劃以增加領導層的多元性。"},{"en":"Diversity fosters creativity and broader perspectives.","zh-TW":"多元性培養創造力和更廣泛的視角。"}]', '{"adjective":"diverse","verb":"diversify"}', NULL, 3, 1059, NULL),
(1060, 'divestiture', '/daɪˈvestɪtʃər/', 'noun', '{"zh-TW":["資產剝離；出售"],"en":["the process of selling off a subsidiary or assets"]}', NULL, 'asset divestiture / forced divestiture', '[{"en":"The divestiture of non-core assets raised $200 million.","zh-TW":"剝離非核心資產籌集了2億美元。"},{"en":"Regulators required a divestiture to approve the merger.","zh-TW":"監管機構要求資產剝離以批准合併。"}]', '{"verb":"divest","adjective":"divested"}', NULL, 4, 1060, 777),
(1061, 'divide', '/dɪˈvaɪd/', 'verb', '{"zh-TW":["劃分；除以"],"en":["to separate into parts"]}', NULL, 'divide into/among', '[{"en":"The project is divided into three phases.","zh-TW":"該項目分為三個階段。"},{"en":"Profits were divided equally among partners.","zh-TW":"利潤在合夥人之間平均分配。"}]', '{"noun":"division","verb":"divide"}', NULL, 2, 1061, NULL),
(1062, 'dividend', '/ˈdɪvɪdend/', 'noun', '{"zh-TW":["股利；紅利"],"en":["a portion of company profits distributed to shareholders"]}', NULL, 'pay a dividend / dividend yield / dividend per share / cut dividends', '[{"en":"The board declared a quarterly dividend of $0.50 per share.","zh-TW":"董事會宣佈每股季度股利為0.50美元。"},{"en":"Investors favored stocks with consistent dividend payments.","zh-TW":"投資者偏好股利持續發放的股票。"}]', '{"adjective":"dividend-paying"}', NULL, 3, 1062, NULL),
(1063, 'division', 'dɪˈvɪʒən', 'noun', '{"zh-TW":["部門；分部","劃分"],"en":["a section of an organization","the act of dividing"]}', NULL, 'sales division/business division', '[{"en":"The Asia division reported record profits.","zh-TW":"亞洲部門報告了創紀錄的利潤。"}]', '{"verb":"divide","adjective":"divisional","adverb":"divisionally"}', NULL, 3, 1063, 338),
(1064, 'doctrine', '/ˈdɒktrɪn/', 'noun', '{"zh-TW":["教義；學說"],"en":["a set of beliefs or principles held by a group"]}', '{"root":{"text":"doct","meaning":"teach (教導)"},"suffix":{"text":"-rine","meaning":"thing (事物)"},"logic":"被教導的東西，即「教義」。"}', 'political doctrine / legal doctrine', '[{"en":"The party changed its economic doctrine.","zh-TW":"該黨改變了其經濟學說。"},{"en":"This is a fundamental doctrine of the religion.","zh-TW":"這是該宗教的基本教義。"}]', NULL, NULL, 3, 1064, NULL),
(1065, 'document', '/ˈdɑːkjumənt/', 'noun / verb', '{"zh-TW":["文件；記錄"],"en":["a written or printed paper; to record"]}', NULL, 'official document', '[{"en":"Please submit all required documents.","zh-TW":"請提交所有必要的文件。"},{"en":"Everything must be documented carefully.","zh-TW":"一切都必須仔細記錄。"}]', '{"noun":"document/documentation","verb":"document"}', NULL, 3, 1065, 107),
(1066, 'documentary', '/ˌdɒkjuˈmɛntəri/', 'noun', '{"zh-TW":["紀錄片"],"en":["a film based on real events"]}', NULL, 'nature documentary / documentary film', '[{"en":"I watched a documentary about climate change.","zh-TW":"我看了一部關於氣候變遷的紀錄片。"},{"en":"She directed an award-winning documentary.","zh-TW":"她執導了一部獲獎紀錄片。"}]', NULL, NULL, 4, 1066, NULL),
(1067, 'documentation', 'ˌdɒkjʊmɛnˈteɪʃən', 'noun', '{"zh-TW":["文件；記錄","文檔"],"en":["written records","the act of documenting"]}', NULL, 'proper documentation/submit documentation', '[{"en":"Please submit complete documentation.","zh-TW":"請提交完整的文件。"}]', '{"verb":"document","adjective":"documented"}', NULL, 5, 1067, 551),
(1068, 'dog', '/dɒɡ/', 'noun', '{"zh-TW":["狗"],"en":["a common domestic animal"]}', NULL, 'guide dog / dog-eat-dog', '[{"en":"It is a dog-eat-dog world in sales.","zh-TW":"銷售業是個競爭激烈的世界。"},{"en":"Some offices allow employees to bring dogs.","zh-TW":"有些辦公室允許員工帶狗。"}]', '{"noun":"dog"}', NULL, 1, 1068, NULL),
(1069, 'dollar', '/ˈdɒlər/', 'noun', '{"zh-TW":["美元"],"en":["the basic unit of money in the US"]}', NULL, 'dollar sign / dollar amount', '[{"en":"The total comes to 500 dollars.","zh-TW":"總共是500美元。"},{"en":"The dollar weakened against the euro.","zh-TW":"美元對歐元貶值了。"}]', '{"noun":"dollar"}', NULL, 2, 1069, NULL),
(1070, 'domain', '/doʊˈmeɪn/', 'noun', '{"zh-TW":["網域；領域","領域；域"],"en":["an area of activity; a website address","an area of knowledge or activity","an internet address"]}', '{"root":{"text":"domin","meaning":"lord/master (主人)"},"logic":"主人管轄的範圍，即「領域」。"}', 'domain name / public domain; public domain / domain name / domain knowledge', '[{"en":"Register a domain name for your website.","zh-TW":"為你的網站註冊一個網域名稱。"},{"en":"That''s outside my domain of expertise.","zh-TW":"那不在我的專業領域內。"},{"en":"This issue falls outside my domain of expertise.","zh-TW":"這個問題不在我的專業領域範圍內。"},{"en":"She registered a new domain name for her website.","zh-TW":"她為網站註冊了一個新網域名稱。"}]', NULL, NULL, 2, 1070, NULL),
(1071, 'domestic', '/dəˈmestɪk/', 'adjective', '{"zh-TW":["國內的；家庭的"],"en":["relating to one''s own country; relating to home"]}', NULL, 'domestic market/flight', '[{"en":"Domestic sales increased by 15%.","zh-TW":"國內銷售額增長了15%。"},{"en":"The airline offers both domestic and international flights.","zh-TW":"該航空公司提供國內和國際航班。"}]', '{"adjective":"domestic","adverb":"domestically"}', NULL, 3, 1071, 339),
(1072, 'dominate', '/ˈdɑːmɪneɪt/', 'verb', '{"zh-TW":["主導；支配","主宰；支配"],"en":["to have control or influence over","to have a commanding influence over"]}', '{"root":{"text":"domin","meaning":"lord/master (主人)"},"suffix":{"text":"-ate","meaning":"make (使)"},"logic":"使自己成為主人，即「支配」。"}', 'dominate the market; dominate the market / dominate the conversation', '[{"en":"The company dominates the smartphone market.","zh-TW":"該公司主導智慧型手機市場。"},{"en":"One topic dominated the meeting.","zh-TW":"一個話題主導了會議。"},{"en":"The company dominates the smartphone market.","zh-TW":"這家公司主宰了智慧型手機市場。"},{"en":"He tends to dominate conversations.","zh-TW":"他往往主導談話。"}]', '{"noun":"dominance","verb":"dominate","adjective":"dominant","noun2":"dominance"}', NULL, 3, 1072, NULL),
(1073, 'donate', '/ˈdoʊneɪt/', 'verb', '{"zh-TW":["捐贈；捐獻","捐贈"],"en":["to give money or goods to a cause","to give money or goods for a good cause"]}', '{"root":{"text":"don","meaning":"give (給予)"},"suffix":{"text":"-ate","meaning":"make (使)"},"logic":"使給予，即「捐贈」。"}', 'donate money/blood; donate money / donate blood / donate to charity', '[{"en":"She donated $10,000 to charity.","zh-TW":"她捐了一萬美元給慈善機構。"},{"en":"Many employees donated blood.","zh-TW":"許多員工捐了血。"},{"en":"She donated $1000 to the charity.","zh-TW":"她捐了1000美元給慈善機構。"},{"en":"Would you like to donate blood?","zh-TW":"你願意捐血嗎？"}]', '{"noun":"donation/donor","verb":"donate","noun2":"donor"}', NULL, 2, 1073, NULL),
(1074, 'door', '/dɔːr/', 'noun', '{"zh-TW":["門"],"en":["a movable barrier at the entrance"]}', NULL, 'next door / open door policy', '[{"en":"Our office has an open door policy.","zh-TW":"我們辦公室有開放門戶政策。"},{"en":"Please close the door behind you.","zh-TW":"請隨手關門。"}]', '{"noun":"door","noun2":"doorway"}', NULL, 1, 1074, NULL),
(1075, 'dormitory', '/ˈdɔːrmɪtɔːri/', 'noun', '{"zh-TW":["宿舍"],"en":["a building where students live at school"]}', NULL, 'dormitory room / student dormitory', '[{"en":"First-year students live in the dormitory.","zh-TW":"大一學生住在宿舍。"},{"en":"The dormitory has a shared kitchen.","zh-TW":"宿舍有共用廚房。"}]', NULL, NULL, 3, 1075, NULL),
(1076, 'dosage', '/ˈdəʊsɪdʒ/', 'noun', '{"zh-TW":["劑量；用量"],"en":["the amount of medicine to be taken at one time"]}', NULL, 'recommended dosage / correct dosage', '[{"en":"Follow the recommended dosage on the label.","zh-TW":"請遵照標籤上的建議劑量服用。"},{"en":"The dosage must be adjusted for elderly patients.","zh-TW":"老年病患的劑量必須調整。"}]', '{"noun":"dose","verb":"dose"}', NULL, 2, 1076, NULL),
(1077, 'dose', '/doʊs/', 'noun', '{"zh-TW":["劑量"],"en":["a quantity of medicine taken at one time"]}', '{"root":{"text":"dose","meaning":"giving (給予)"},"logic":"源自希臘語 dosis（給予的量）。"}', 'recommended dose / daily dose / overdose', '[{"en":"Take one dose every four hours.","zh-TW":"每四小時服用一劑。"},{"en":"The doctor increased the dose of medication.","zh-TW":"醫生增加了藥物劑量。"}]', '{"noun":"dosage","verb":"dose"}', NULL, 1, 1077, NULL),
(1078, 'dossier', '/ˈdɒsieɪ/', 'noun', '{"zh-TW":["檔案；案卷"],"en":["a collection of documents about a particular person or topic"]}', NULL, 'compile a dossier / confidential dossier / submit a dossier', '[{"en":"The team compiled a dossier on each potential acquisition target.","zh-TW":"團隊針對每個潛在收購目標編制了檔案。"},{"en":"A dossier of evidence was submitted to the regulatory authority.","zh-TW":"一份證據案卷被提交給監管機構。"}]', NULL, NULL, 3, 1078, NULL),
(1079, 'double', 'ˈdʌbəl', 'adjective', '{"zh-TW":["雙倍的；兩倍的","雙重的"],"en":["twice as much","having two parts"]}', NULL, 'double the budget/double-check', '[{"en":"Sales doubled compared to last year.","zh-TW":"銷售額與去年相比翻倍。"}]', '{"verb":"double","adverb":"doubly"}', NULL, 2, 1079, NULL),
(1080, 'double-entry', '/ˈdʌbəl ˈɛntri/', 'adjective', '{"zh-TW":["複式記帳的"],"en":["a bookkeeping system where each transaction is recorded twice"]}', NULL, 'double-entry bookkeeping / double-entry accounting', '[{"en":"Double-entry bookkeeping ensures all transactions balance.","zh-TW":"複式記帳確保所有交易保持平衡。"},{"en":"Accountants use double-entry bookkeeping to prevent errors.","zh-TW":"會計師使用複式記帳來防止錯誤。"}]', NULL, NULL, 4, 1080, NULL),
(1081, 'doubt', '/daʊt/', 'noun', '{"zh-TW":["懷疑；疑慮"],"en":["a feeling of uncertainty"]}', NULL, 'no doubt / beyond doubt', '[{"en":"There is no doubt about his ability.","zh-TW":"他的能力毫無疑問。"},{"en":"I doubt that will work.","zh-TW":"我懷疑那行不通。"}]', '{"noun":"doubt","verb":"doubt","adjective":"doubtful","adverb":"doubtfully"}', NULL, 2, 1081, NULL),
(1082, 'downgrade', '/ˈdaʊnɡreɪd/', 'verb', '{"zh-TW":["降級；下調評級"],"en":["to reduce the grade, status, or rating of something"]}', NULL, 'downgrade a credit rating / stock downgraded', '[{"en":"The credit agency downgraded the company''s bond rating to junk.","zh-TW":"信用評級機構將公司的債券評級下調至垃圾級。"},{"en":"The analyst downgraded the stock from buy to hold.","zh-TW":"分析師將股票從買入下調至持有。"}]', '{"noun":"downgrade","adjective":"downgraded"}', NULL, 3, 1082, NULL),
(1083, 'download', '/ˈdaʊnloʊd/', 'verb', '{"zh-TW":["下載"],"en":["to copy data from the internet to a computer"]}', NULL, 'download a file / free download', '[{"en":"Download the app for free.","zh-TW":"免費下載這個應用程式。"},{"en":"The download is almost complete.","zh-TW":"下載快要完成了。"}]', '{"noun":"download"}', NULL, 3, 1083, NULL),
(1084, 'downsize', '/ˈdaʊnsaɪz/', 'verb', '{"zh-TW":["縮編；裁員"],"en":["to reduce the size or number of employees in an organization"]}', NULL, 'downsize the workforce / company downsizing', '[{"en":"The firm downsized its operations after the market contracted.","zh-TW":"市場萎縮後，公司縮減了其運營規模。"},{"en":"Thousands of employees were laid off during the downsizing.","zh-TW":"在縮編過程中，數千名員工被裁員。"}]', '{"noun":"downsizing","adjective":"downsized"}', NULL, 3, 1084, 674),
(1085, 'downsizing', '/ˈdaʊnsaɪzɪŋ/', 'noun', '{"zh-TW":["裁員；縮減規模"],"en":["reducing the size of a workforce or organization"]}', NULL, 'corporate downsizing / downsizing plan', '[{"en":"Downsizing was necessary to cut operating costs.","zh-TW":"裁員是削減營運成本的必要措施。"},{"en":"The downsizing affected nearly every department.","zh-TW":"裁員幾乎影響到每個部門。"}]', '{"verb":"downsize","noun":"downsizer"}', NULL, 4, 1085, NULL),
(1086, 'downstream', '/ˈdaʊnstriːm/', 'adjective', '{"zh-TW":["下游的"],"en":["relating to the later stages of production or supply chain activities"]}', NULL, 'downstream distribution / downstream partner / downstream operations', '[{"en":"Downstream operations include packaging, distribution, and retail.","zh-TW":"下游運營包括包裝、分銷和零售。"},{"en":"Disruptions in downstream channels delay goods reaching end consumers.","zh-TW":"下游渠道的中斷延遲了商品到達最終消費者的時間。"}]', '{"opposite":"upstream"}', NULL, 4, 1086, 863),
(1087, 'downtime', '/ˈdaʊntaɪm/', 'noun', '{"zh-TW":["停機時間；系統停運"],"en":["a period when a system is not operational"]}', NULL, 'minimize downtime / planned downtime / unexpected downtime / downtime cost', '[{"en":"The system downtime lasted three hours due to a hardware failure.","zh-TW":"由於硬體故障，系統停機持續了三小時。"},{"en":"Unplanned downtime can cost millions in lost revenue.","zh-TW":"計劃外停機可能導致數百萬元的收入損失。"}]', '{"antonym":"uptime"}', NULL, 3, 1087, NULL),
(1088, 'downturn', '/ˈdaʊntɜːrn/', 'noun', '{"zh-TW":["低迷；下滑"],"en":["a decline in economic or business activity"]}', NULL, 'economic downturn / market downturn', '[{"en":"The economic downturn affected all sectors.","zh-TW":"經濟低迷影響了所有行業。"},{"en":"We survived the downturn by cutting costs.","zh-TW":"我們靠削減成本度過了低迷期。"}]', '{"noun":"downturn"}', NULL, 3, 1088, 778),
(1089, 'dozen', 'ˈdʌzən', 'noun', '{"zh-TW":["一打；十二個","很多"],"en":["a group of twelve","a large number"]}', NULL, 'a dozen/dozens of', '[{"en":"We ordered a dozen new computers.","zh-TW":"我們訂購了十二台新電腦。"}]', NULL, NULL, 2, 1089, NULL),
(1090, 'draft', '/dræft/', 'noun / verb', '{"zh-TW":["草稿；起草","草稿；草案"],"en":["a preliminary version; to write a first version","a preliminary version of a document"]}', '{"root":{"text":"draft","meaning":"draw (拉/畫)"},"logic":"源自 draw 的變體，指拉出的初步版本。"}', 'first/final draft; first draft / rough draft / draft proposal', '[{"en":"Please review the first draft of the proposal.","zh-TW":"請審閱提案的初稿。"},{"en":"He drafted the contract in one day.","zh-TW":"他一天內起草了合約。"},{"en":"I finished the first draft of my essay.","zh-TW":"我完成了論文的初稿。"},{"en":"The committee reviewed the draft proposal.","zh-TW":"委員會審查了提案草案。"}]', '{"noun":"draft","verb":"draft"}', NULL, 2, 1090, 340),
(1091, 'drafting', '/ˈdrɑːftɪŋ/', 'noun', '{"zh-TW":["起草；草擬"],"en":["the process of writing an initial version of a document"]}', NULL, 'contract drafting / drafting a proposal / drafting process', '[{"en":"Contract drafting requires precision to avoid ambiguities.","zh-TW":"合約起草需要精確以避免歧義。"},{"en":"The drafting process for the terms of service took three weeks.","zh-TW":"服務條款的草擬過程耗時三週。"}]', '{"verb":"draft","noun":"draft"}', NULL, 3, 1091, NULL),
(1092, 'drain', '/dreɪn/', 'verb / noun', '{"zh-TW":["排水；耗盡"],"en":["to remove liquid; to use up resources","to remove liquid","to use up resources gradually"]}', '{"root":{"text":"drain","meaning":"dry (乾)"},"logic":"源自古英語 dreahnian（變乾），使水排去。"}', 'drain resources/energy; drain resources / brain drain / drain the water', '[{"en":"The project drained our budget.","zh-TW":"這個項目耗盡了我們的預算。"},{"en":"Brain drain is a serious issue for developing countries.","zh-TW":"人才外流對開發中國家是嚴重問題。"},{"en":"Please drain the water from the pool.","zh-TW":"請把游泳池的水排掉。"},{"en":"The long commute drains my energy.","zh-TW":"長途通勤耗盡我的精力。"}]', '{"noun":"drain/drainage","verb":"drain","noun2":"drainage"}', NULL, 2, 1092, NULL),
(1093, 'drama', '/ˈdrɑːmə/', 'noun', '{"zh-TW":["戲劇；戲劇性事件"],"en":["a play or performance for theater or TV"]}', NULL, 'drama series / drama queen', '[{"en":"She studied drama at university.","zh-TW":"她在大學學戲劇。"},{"en":"There''s always so much drama at work.","zh-TW":"工作中總是有那麼多戲劇性的事。"}]', '{"adjective":"dramatic","adverb":"dramatically"}', NULL, 2, 1093, NULL),
(1094, 'dramatic', '/drəˈmætɪk/', 'adjective', '{"zh-TW":["戲劇性的；顯著的","戲劇性的；巨大的"],"en":["sudden and striking; relating to drama","sudden and striking","relating to drama"]}', '{"root":{"text":"drama","meaning":"action/play (行動/戲)"},"suffix":{"text":"-tic","meaning":"relating to (相關的)"},"logic":"與戲劇性行動相關的。"}', 'dramatic increase/change; dramatic change / dramatic increase / dramatic effect', '[{"en":"There was a dramatic increase in profits.","zh-TW":"利潤有了顯著的增長。"},{"en":"The market saw dramatic changes.","zh-TW":"市場出現了劇烈的變化。"},{"en":"There has been a dramatic increase in sales.","zh-TW":"銷售額有了大幅增加。"},{"en":"The sunset was dramatic and beautiful.","zh-TW":"日落壯觀而美麗。"}]', '{"noun":"drama","adjective":"dramatic","adverb":"dramatically"}', NULL, 3, 1094, NULL),
(1095, 'draw', 'drɔː', 'verb', '{"zh-TW":["【主要意義-動詞】畫；拉；拔出","【次要意義-名詞】平局（比賽）","【次要意義-動詞】引起（注意/興趣）","【次要意義-動詞】（從帳戶）提取；得出（結論）"],"en":["[primary] to make a picture; to pull something","[secondary - noun] a tied result in a game or contest","[secondary - verb] to attract or pull in attention or interest","[secondary - verb] to withdraw money; to reach a conclusion"]}', NULL, 'draw a conclusion / draw attention to / draw on experience / draw up a contract', '[{"en":"The new product drew considerable attention at the trade fair.","zh-TW":"新產品在貿易展覽會上引起了相當大的關注。"},{"en":"The report draws on data collected over five years.","zh-TW":"報告借鑒了五年來收集的數據。"},{"en":"We can draw the conclusion that customer satisfaction has improved.","zh-TW":"我們可以得出結論，客戶滿意度已有所提高。"}]', '{"noun":"drawback, withdrawal"}', 'draw 有多個次要意義：draw attention（引起注意）、draw on（借鑒/依靠）、draw a conclusion（得出結論）、draw up a contract（起草合約），均為 TOEIC 高頻商業用語。', 1, 1095, NULL),
(1096, 'draw-down', '/ˈdrɔː daʊn/', 'noun', '{"zh-TW":["提款；資金提取"],"en":["the act of accessing funds from an available credit facility or loan"]}', NULL, 'draw-down schedule / draw-down on the credit line', '[{"en":"The company made a draw-down of $2 million from its credit facility.","zh-TW":"公司從其信貸額度提取了200萬元。"},{"en":"Multiple draw-downs are allowed under the revolving credit agreement.","zh-TW":"循環信貸協議允許多次提款。"}]', '{"verb":"draw down"}', NULL, 3, 1096, NULL),
(1097, 'drawback', '/ˈdrɔːbæk/', 'noun', '{"zh-TW":["缺點；不利之處"],"en":["a disadvantage or negative aspect of something"]}', NULL, 'main drawback / overcome the drawback', '[{"en":"The main drawback of the system is its high implementation cost.","zh-TW":"該系統的主要缺點是其高昂的實施成本。"},{"en":"The proposal was accepted despite its drawbacks.","zh-TW":"儘管有缺點，提案還是被接受了。"}]', NULL, NULL, 3, 1097, NULL),
(1098, 'drawdown', '/ˈdrɔːdaʊn/', 'noun', '{"zh-TW":["提款；資金提取"],"en":["the withdrawal of funds from a credit facility or investment account"]}', NULL, 'request a drawdown / drawdown schedule', '[{"en":"The company made a drawdown from its credit facility to fund operations.","zh-TW":"公司從信貸額度中提取資金以資助運營。"},{"en":"Each drawdown from the revolving credit was subject to lender approval.","zh-TW":"每次從循環信用中提取資金都需要貸款方批准。"}]', '{"verb":"draw down"}', NULL, 3, 1098, NULL),
(1099, 'dream', '/driːm/', 'noun', '{"zh-TW":["夢想；夢"],"en":["a hope or ambition","images during sleep"]}', NULL, 'dream job / dream come true', '[{"en":"This is my dream job.","zh-TW":"這是我的夢想工作。"},{"en":"Starting my own business was a dream come true.","zh-TW":"創業是我夢想成真。"}]', '{"noun":"dream","verb":"dream","adjective":"dreamy","noun2":"dreamer"}', NULL, 2, 1099, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(1100, 'dressing', '/ˈdrɛsɪŋ/', 'noun', '{"zh-TW":["醬汁；調味醬"],"en":["a sauce or mixture used to flavor salads"]}', NULL, 'salad dressing / house dressing', '[{"en":"What dressing would you like on your salad?","zh-TW":"您的沙拉要什麼醬汁？"},{"en":"The house dressing is made with lemon and olive oil.","zh-TW":"本店醬汁是用檸檬和橄欖油製成的。"}]', NULL, NULL, 3, 1100, NULL),
(1101, 'drink', '/drɪŋk/', 'verb', '{"zh-TW":["喝；飲料"],"en":["to take liquid into the mouth","a liquid for drinking"]}', NULL, 'soft drink / drink water', '[{"en":"Would you like something to drink?","zh-TW":"你想喝點什麼嗎？"},{"en":"Soft drinks are available in the lounge.","zh-TW":"休息室有提供軟性飲料。"}]', '{"verb":"drink","noun":"drink","noun2":"drinker"}', NULL, 2, 1101, NULL),
(1102, 'drive', '/draɪv/', 'verb', '{"zh-TW":["開車；驅動"],"en":["to operate a vehicle","to cause something to happen"]}', NULL, 'drive growth / drive to work', '[{"en":"Innovation drives our growth.","zh-TW":"創新驅動我們的成長。"},{"en":"She drives to work every day.","zh-TW":"她每天開車上班。"}]', '{"verb":"drive","noun":"driver","noun2":"drive"}', NULL, 2, 1102, NULL),
(1103, 'drop', '/drɑːp/', 'verb / noun', '{"zh-TW":["下降；放棄"],"en":["to fall or decrease; to stop doing"]}', NULL, 'drop in price/sales', '[{"en":"Sales dropped by 5% last month.","zh-TW":"上個月銷售額下降了5%。"},{"en":"They decided to drop the project.","zh-TW":"他們決定放棄這個項目。"}]', '{"noun":"drop","verb":"drop"}', NULL, 1, 1103, NULL),
(1104, 'drought', '/draʊt/', 'noun', '{"zh-TW":["乾旱"],"en":["a prolonged period of abnormally low rainfall"]}', '{"root":{"text":"drought","meaning":"dryness (乾燥)"},"logic":"源自古英語 drugaþ（乾燥），指長期缺水。"}', 'severe drought / drought-resistant', '[{"en":"The drought destroyed most of the crops.","zh-TW":"乾旱摧毀了大部分的農作物。"},{"en":"The region is experiencing its worst drought in decades.","zh-TW":"該地區正經歷數十年來最嚴重的乾旱。"}]', NULL, NULL, 3, 1104, NULL),
(1105, 'dry', '/draɪ/', 'adjective', '{"zh-TW":["乾的；乾燥的"],"en":["not wet; without water"]}', NULL, 'dry season / dry cleaning', '[{"en":"The dry season affects our water supply.","zh-TW":"旱季影響我們的供水。"},{"en":"This suit needs dry cleaning.","zh-TW":"這套西裝需要乾洗。"}]', '{"adjective":"dry","verb":"dry","noun":"dryer","noun2":"drought"}', NULL, 1, 1105, NULL),
(1106, 'due', '/djuː/', 'adjective', '{"zh-TW":["到期的；應付的"],"en":["expected at a certain time; owed"]}', NULL, 'due date/due to', '[{"en":"The payment is due on the 15th.","zh-TW":"付款到期日是15號。"},{"en":"The delay was due to bad weather.","zh-TW":"延誤是由於惡劣天氣。"}]', '{"adjective":"due"}', NULL, 1, 1106, 341),
(1107, 'duly', '/ˈdjuːli/', 'adverb', '{"zh-TW":["正式地；如期地"],"en":["in accordance with what is required; at the proper time"]}', NULL, 'duly signed / duly authorized / duly noted', '[{"en":"The contract was duly signed by both parties.","zh-TW":"合約由雙方正式簽署。"},{"en":"All submissions must be duly completed before the deadline.","zh-TW":"所有提交文件必須在截止日期前正式完成。"}]', '{"adjective":"due"}', NULL, 1, 1107, NULL),
(1108, 'duplicate', '/ˈdjuːplɪkeɪt/', 'verb / noun', '{"zh-TW":["複製；副本"],"en":["to make an exact copy"]}', NULL, 'avoid duplication', '[{"en":"Please duplicate this report for all managers.","zh-TW":"請為所有經理複製這份報告。"},{"en":"We need to eliminate duplicate records.","zh-TW":"我們需要消除重複的記錄。"}]', '{"noun":"duplicate/duplication","verb":"duplicate"}', NULL, 3, 1108, 675),
(1109, 'duration', '/djuˈreɪʃən/', 'noun', '{"zh-TW":["持續時間"],"en":["the time during which something continues","the length of time something continues"]}', '{"root":{"text":"dur","meaning":"last/hard (持久)"},"suffix":{"text":"-ation","meaning":"state (狀態)"},"logic":"持續的狀態，即「持續時間」。"}', 'for the duration of; for the duration of / short duration', '[{"en":"The contract is valid for the duration of the project.","zh-TW":"合約在項目期間有效。"},{"en":"What is the duration of the training?","zh-TW":"培訓的持續時間是多長？"},{"en":"The flight duration is approximately 12 hours.","zh-TW":"飛行時間約12小時。"},{"en":"For the duration of the event, parking is free.","zh-TW":"活動期間停車免費。"}]', '{"noun":"duration","adjective":"durable","verb":"endure"}', NULL, 3, 1109, 108),
(1110, 'duty', '/ˈdjuːti/', 'noun', '{"zh-TW":["職責；關稅"],"en":["a moral or legal obligation; a tax on imports"]}', NULL, 'on/off duty', '[{"en":"It is your duty to report any safety issues.","zh-TW":"報告任何安全問題是你的職責。"},{"en":"Import duties have been raised.","zh-TW":"進口關稅已提高。"}]', '{"noun":"duty","adjective":"dutiful"}', NULL, 1, 1110, NULL),
(1111, 'duty-free', '/ˈdjuːtiˌfriː/', 'adjective', '{"zh-TW":["免稅的"],"en":["not taxed, especially goods sold at airports"]}', NULL, 'duty-free shop / duty-free allowance', '[{"en":"Passengers can buy duty-free goods before boarding.","zh-TW":"乘客可以在登機前購買免稅商品。"},{"en":"The duty-free allowance is one liter of alcohol.","zh-TW":"免稅限額是一升酒精。"}]', NULL, NULL, 3, 1111, NULL),
(1112, 'dwell', '/dwel/', 'verb', '{"zh-TW":["居住；老是想著"],"en":["to live in a place","to think about something at length"]}', '{"root":{"text":"dwell","meaning":"lead astray/delay (耽擱)"},"logic":"源自古英語 dwellan（耽擱），引申為停留、居住。"}', 'dwell on / dwell in / dwelling place', '[{"en":"Don''t dwell on past mistakes.","zh-TW":"不要老想著過去的錯誤。"},{"en":"Many species dwell in the rainforest.","zh-TW":"許多物種棲息在雨林中。"}]', '{"noun":"dwelling","noun2":"dweller"}', NULL, 2, 1112, NULL),
(1113, 'dynamic', '/daɪˈnæmɪk/', 'adjective', '{"zh-TW":["動態的；有活力的","動態的；充滿活力的"],"en":["characterized by constant change and activity","characterized by constant change or activity"]}', '{"root":{"text":"dynam","meaning":"power (力量)"},"suffix":{"text":"-ic","meaning":"relating to (相關的)"},"logic":"與力量和活動相關的，即「動態的」。"}', 'dynamic environment/market; dynamic environment / dynamic personality', '[{"en":"The tech industry is highly dynamic.","zh-TW":"科技產業高度動態。"},{"en":"She is a dynamic leader.","zh-TW":"她是一位有活力的領導者。"},{"en":"The business operates in a dynamic market.","zh-TW":"這家企業在活躍的市場中運營。"},{"en":"She has a very dynamic personality.","zh-TW":"她有非常有活力的個性。"}]', '{"noun":"dynamics","adjective":"dynamic","adverb":"dynamically"}', NULL, 3, 1113, 865),
(1114, 'e-commerce', '/ˈiːkɒmɜːrs/', 'noun', '{"zh-TW":["電子商務"],"en":["buying and selling goods and services over the internet"]}', NULL, 'e-commerce platform / B2C e-commerce / e-commerce growth', '[{"en":"E-commerce sales surged during the pandemic.","zh-TW":"疫情期間電子商務銷售額激增。"},{"en":"The brand expanded into e-commerce to reach new customers.","zh-TW":"品牌拓展至電子商務以觸及新客戶。"}]', '{"adjective":"e-commerce"}', NULL, 4, 1114, NULL),
(1115, 'e-learning', '/ˈiː ˌlɜːrnɪŋ/', 'noun', '{"zh-TW":["電子學習；線上學習"],"en":["learning conducted via electronic means, especially online"]}', NULL, 'e-learning platform / e-learning course', '[{"en":"E-learning allows students to study from anywhere.","zh-TW":"電子學習允許學生在任何地方學習。"},{"en":"The company launched an e-learning program for employee development.","zh-TW":"公司推出了員工發展的電子學習計劃。"}]', NULL, NULL, 4, 1115, NULL),
(1116, 'eager', '/ˈiːɡər/', 'adjective', '{"zh-TW":["渴望的；熱切的"],"en":["strongly wanting to do or have something"]}', '{"root":{"text":"eager","meaning":"sharp/keen (尖銳/敏銳)"},"logic":"源自拉丁語 acer（尖銳的），指熱切渴望的。"}', 'eager to learn / eager for', '[{"en":"Students were eager to start the project.","zh-TW":"學生們渴望開始這個專案。"},{"en":"She is eager for new experiences.","zh-TW":"她熱切期望新體驗。"}]', '{"noun":"eagerness","adverb":"eagerly"}', NULL, 2, 1116, NULL),
(1117, 'early', '/ˈɜːrli/', 'adjective', '{"zh-TW":["早的；提前的"],"en":["before the expected time","near the beginning of a period"]}', NULL, 'early morning / early stage', '[{"en":"We are still in the early stages.","zh-TW":"我們仍處於早期階段。"},{"en":"She arrived early for the interview.","zh-TW":"她面試提前到達。"}]', '{"adjective":"early","adverb":"early"}', NULL, 2, 1117, NULL),
(1118, 'earn', '/ɜːrn/', 'verb', '{"zh-TW":["賺取；贏得"],"en":["to receive money for work; to gain through effort"]}', NULL, 'earn a living/reputation', '[{"en":"She earns a good salary as a consultant.","zh-TW":"她作為顧問賺取了不錯的薪水。"},{"en":"He earned the respect of his colleagues.","zh-TW":"他贏得了同事的尊重。"}]', '{"noun":"earnings","verb":"earn"}', NULL, 1, 1118, NULL),
