(1140, 'efficient', '/ɪˈfɪʃənt/', 'adjective', '{"zh-TW":["高效的","有效率的"],"en":["achieving maximum output with minimum waste","achieving maximum productivity with minimum waste"]}', '{"prefix":{"text":"ef-","meaning":"out (出)"},"root":{"text":"fic","meaning":"make/do (做)"},"suffix":{"text":"-ient","meaning":"being (…的)"},"logic":"做出成果的，即「有效率的」。"}', 'cost-efficient / energy-efficient; energy-efficient / cost-efficient / highly efficient', '[{"en":"The new system is more efficient.","zh-TW":"新系統更加高效。"},{"en":"We need to find a more efficient solution.","zh-TW":"我們需要找到更高效的解決方案。"},{"en":"This engine is more fuel-efficient.","zh-TW":"這個引擎更省油。"},{"en":"We need a more efficient way to process orders.","zh-TW":"我們需要更有效率的方式處理訂單。"}]', '{"noun":"efficiency","adjective":"efficient","adverb":"efficiently"}', NULL, 3, 1140, 110),
